def solve(a, b):
    """Return Levenshtein distance between strings a and b."""
    # Ensure a is the shorter for space efficiency
    if len(a) > len(b):
        a, b = b, a
    n, m = len(a), len(b)
    # previous row dp
    prev = list(range(n + 1))
    for j in range(1, m + 1):
        current = [j] + [0] * n
        bj = b[j - 1]
        for i in range(1, n + 1):
            if a[i - 1] == bj:
                cost = 0
            else:
                cost = 1
            current[i] = min(
                current[i - 1] + 1,      # deletion in a (insert in b)
                prev[i] + 1,            # insertion in a (delete in b)
                prev[i - 1] + cost      # substitution
            )
        prev = current
    return prev[n]

