def solve(meetings):
    """Return the maximum number of non‑overlapping meetings.
    Each meeting is given as an iterable where the first two elements are the
    start and end times. Meetings may start exactly when another ends.
    Invalid entries (e.g., not enough elements, start > end) are ignored.
    """
    # Extract valid (start, end) pairs
    intervals = []
    for m in meetings:
        try:
            start, end = m[0], m[1]
        except Exception:
            continue  # skip malformed entry
        if start <= end:
            intervals.append((start, end))
    if not intervals:
        return 0
    # Greedy: sort by end time, then start time
    intervals.sort(key=lambda x: (x[1], x[0]))
    count = 0
    current_end = None
    for start, end in intervals:
        if current_end is None or start >= current_end:
            count += 1
            current_end = end
    return count

