def solve(mat):
    # Empty matrix determinant is defined as 1
    if not mat:
        return 1
    n = len(mat)
    # Ensure square
    for row in mat:
        if len(row) != n:
            raise ValueError('Non-square matrix')
    # Use Bareiss algorithm (fraction-free Gaussian elimination)
    # Make a copy to avoid mutating input
    A = [list(map(int, row)) for row in mat]
    det = 1
    for k in range(n-1):
        # Find pivot if zero
        if A[k][k] == 0:
            # Find a row below with non-zero in column k
            swap = None
            for i in range(k+1, n):
                if A[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0
            # Swap rows
            A[k], A[swap] = A[swap], A[k]
            det = -det
        pivot = A[k][k]
        for i in range(k+1, n):
            for j in range(k+1, n):
                # A[i][j] = (pivot * A[i][j] - A[i][k] * A[k][j]) // (1 if k==0 else A[k-1][k-1])
                A[i][j] = (pivot * A[i][j] - A[i][k] * A[k][j]) // (A[k-1][k-1] if k>0 else 1)
        # Zero out column below pivot
        for i in range(k+1, n):
            A[i][k] = 0
    # Determinant is det * last diagonal element
    det *= A[n-1][n-1]
    return det

