def solve(n, edges):
    """Return the lexicographically smallest topological ordering of a DAG.
    Duplicate edges are ignored. If a cycle exists, return [] .
    """
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    seen = set()
    for a, b in edges:
        if not (0 <= a < n and 0 <= b < n):
            continue
        if (a, b) in seen:
            continue
        seen.add((a, b))
        adj[a].append(b)
        indeg[b] += 1
    heap = [i for i in range(n) if indeg[i] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)
    if len(order) != n:
        return []
    return order
