def solve(words, width):
    """Greedy word wrap.
    words: list of strings
    width: int, max line length.
    Returns list of lines packed greedily.
    """
    lines = []
    current = ''
    for w in words:
        if not current:
            # start new line with word
            current = w
        else:
            # try to add with a space
            if len(current) + 1 + len(w) <= width:
                current += ' ' + w
            else:
                lines.append(current)
                current = w
    if current:
        lines.append(current)
    return lines

