    dist[0]=0
    pq=[(0,0)]
    while pq:
        d,u=heapq.heappop(pq)
        if d!=dist[u]:
            continue
        if u==n-1:
            break
        for v,w in adj[u]:
            nd=d+w
            if nd<dist[v]:
                dist[v]=nd
                heapq.heappush(pq,(nd,v))
